(1288162, 166102, 35675, '<td valign="top">The sun can either make or break your picture and it sure MADE yours! Nice job!<br/>Lucky to have such great architecture nearby!</td>', 'The sun can either make or break your picture and it sure MADE yours! Nice job!Lucky to have such great architecture nearby!', '2005-04-13 10:20:34.000000', NULL, 1),
(1288165, 164236, 35804, '<td valign="top">Lovely textures, the subtle color is also a very nice touch.</td>', 'Lovely textures, the subtle color is also a very nice touch.', '2005-04-13 10:21:07.000000', NULL, 1),
(1288166, 164370, 34789, '<td valign="top">nice photo, nice way to use a one-color theme in this photo, makes it look older and more abandoned</td>', 'nice photo, nice way to use a one-color theme in this photo, makes it look older and more abandoned', '2005-04-13 10:21:21.000000', NULL, 1),
