(1288519, 165902, 13879, '<td valign="top">if only the sky was blue! nice shot all the same, good composition.</td>', 'if only the sky was blue! nice shot all the same, good composition.', '2005-04-13 12:45:23.000000', NULL, 1),
(1288520, 165858, 25111, '<td valign="top">This is a good image. The forground is well placed and adds great depth to the pic.<br/>A good angle for the house and the sky is great. <br/></td>', 'This is a good image. The forground is well placed and adds great depth to the pic.A good angle for the house and the sky is great. ', '2005-04-13 12:45:34.000000', NULL, 1),
