(1288543, 165480, 36355, '<td valign="top">Nice.</td>', 'Nice.', '2005-04-13 13:10:11.000000', NULL, 1),
(1288544, 165894, 23653, '<td valign="top">A very nice subject, but I feel that somehow it be composed in a more dramatic way...7</td>', 'A very nice subject, but I feel that somehow it be composed in a more dramatic way...7', '2005-04-13 13:10:29.000000', NULL, 1),
(1288547, 165742, 19178, '<td valign="top">This makes an interesting composition.  I''d like to have seen a bit more shadow detail.</td>', 'This makes an interesting composition.  I''d like to have seen a bit more shadow detail.', '2005-04-13 13:11:21.000000', NULL, 1),
(1288548, 165086, 35513, '<td valign="top">Perhaps I misread things, but I thought that only basic editing was allowed in this challenge.  I like the house, but to be honest, I feel that the ghostly image detracts from the picture.</td>', 'Perhaps I misread things, but I thought that only basic editing was allowed in this challenge.  I like the house, but to be honest, I feel that the ghostly image detracts from the picture.', '2005-04-13 13:11:34.000000', NULL, 1),
(1288549, 163854, 31541, '<td valign="top">Nice castle, but the photo seems a bit washed out to me (not sure if this was done on purpose).  The top left side takes away from the rest of the picture.</td>', 'Nice castle, but the photo seems a bit washed out to me (not sure if this was done on purpose).  The top left side takes away from the rest of the picture.', '2005-04-13 13:12:30.000000', NULL, 1),
(1288551, 165736, 19178, '<td valign="top">Nicely  framed!</td>', 'Nicely  framed!', '2005-04-13 13:13:26.000000', NULL, 1),
(1288552, 165481, 36355, '<td valign="top">This is such a lovely photo, but the barn doesn''t actually appear to be abandoned. Benefit of the doubt gives a 9.</td>', 'This is such a lovely photo, but the barn doesn''t actually appear to be abandoned. Benefit of the doubt gives a 9.', '2005-04-13 13:13:34.000000', NULL, 1),
