INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1288565, 165946, 19178, '<td valign="top">Nicely done.  I''m not sure this is a "building" but I like it anyway.</td>', 'Nicely done.  I''m not sure this is a "building" but I like it anyway.', '2005-04-13 13:19:04.000000', NULL, 1),
(1288566, 166003, 36355, '<td valign="top">Oooh... like!</td>', 'Oooh... like!', '2005-04-13 13:19:20.000000', NULL, 1),
(1288571, 165222, 29148, '<td valign="top">Good "texture" makes this stand out from other ho-hum photos.</td>', 'Good "texture" makes this stand out from other ho-hum photos.', '2005-04-13 13:21:56.000000', NULL, 1),
(1288574, 164988, 29256, '<td valign="top">Building appears IMO to be a little too dark to show any detail. Too much sky.</td>', 'Building appears IMO to be a little too dark to show any detail. Too much sky.', '2005-04-13 13:23:30.000000', NULL, 1),
(1288575, 165333, 35513, '<td valign="top">The tree on the right hand side of this shot really inhibits the picture, rather than enhancing it.  Perhaps a different angle would be better.</td>', 'The tree on the right hand side of this shot really inhibits the picture, rather than enhancing it.  Perhaps a different angle would be better.', '2005-04-13 13:23:47.000000', NULL, 1),
(1288576, 165233, 36355, '<td valign="top">Amazing find.  Never seen anything like it.</td>', 'Amazing find.  Never seen anything like it.', '2005-04-13 13:23:50.000000', NULL, 1),
