(1290085, 163945, 33947, '<td valign="top">Fantastic lighting, and beautiful reflection. Nice composition.</td>', 'Fantastic lighting, and beautiful reflection. Nice composition.', '2005-04-13 20:56:48.000000', NULL, 1),
(1290086, 164848, 35675, '<td valign="top">what a pretty picture.  Nice job</td>', 'what a pretty picture.  Nice job', '2005-04-13 20:56:48.000000', NULL, 1),
(1290087, 163950, 31230, '<td valign="top">Nice shadows</td>', 'Nice shadows', '2005-04-13 20:56:54.000000', NULL, 1),
