(1290992, 164350, 26526, '<td valign="top">Very creative pov. Would like to see sharper focus used on the spider webs. Color rather washed out in the window area. I hope this was taken in an abandoned house!</td>', 'Very creative pov. Would like to see sharper focus used on the spider webs. Color rather washed out in the window area. I hope this was taken in an abandoned house!', '2005-04-14 05:21:35.000000', NULL, 1),
(1290993, 166047, 31637, '<td valign="top">very nice. unique find......10</td>', 'very nice. unique find......10', '2005-04-14 05:24:35.000000', NULL, 1),
