(1293972, 165676, 35377, '<td valign="top">I like the colors, but it seems to fuzzy, my eyes have nothing to focus on.</td>', 'I like the colors, but it seems to fuzzy, my eyes have nothing to focus on.', '2005-04-15 13:45:55.000000', NULL, 1),
(1293975, 164317, 28084, '<td valign="top">A positive spin on a unfortunate situation. Nice crop, good work.</td>', 'A positive spin on a unfortunate situation. Nice crop, good work.', '2005-04-15 13:47:20.000000', NULL, 1),
