(1296806, 164583, 19708, '<td valign="top">Interesting perspective / point of view.<br/>A couple suggestions: image would probably look a little better if leveled out, using the roof ridge as a point to level from, and not real sure the title works for me.<br/>Still a good shot regardless.</td>', 'Interesting perspective / point of view.A couple suggestions: image would probably look a little better if leveled out, using the roof ridge as a point to level from, and not real sure the title works for me.Still a good shot regardless.', '2005-04-16 19:42:41.000000', NULL, 1),
(1296807, 164971, 35530, '<td valign="top">Might be more effective if the photo had been straightened.</td>', 'Might be more effective if the photo had been straightened.', '2005-04-16 19:42:50.000000', NULL, 1),
(1296808, 165388, 35169, '<td valign="top">Interesting color adjustments, but the sharpening is overdone to my taste and degradates the image to where it becomes difficult and confused.</td>', 'Interesting color adjustments, but the sharpening is overdone to my taste and degradates the image to where it becomes difficult and confused.', '2005-04-16 19:42:51.000000', NULL, 1),
(1296811, 164827, 19708, '<td valign="top">Dark and moody - I like this.<br/>Without the hat, it would be just another shot. great composition the way you have presented it. Well Done!<br/></td>', 'Dark and moody - I like this.Without the hat, it would be just another shot. great composition the way you have presented it. Well Done!', '2005-04-16 19:44:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1296813, 164680, 35530, '<td valign="top">Interesting building. I don''t like the tones very much.</td>', 'Interesting building. I don''t like the tones very much.', '2005-04-16 19:45:23.000000', NULL, 1),
(1296815, 166014, 35169, '<td valign="top">The color tones make it appear to be a very arid environment (well done if that was your intent) good image.... BUT (of course) the frame would be better if it was less dominent, prhaps the same tone as in the image.</td>', 'The color tones make it appear to be a very arid environment (well done if that was your intent) good image.... BUT (of course) the frame would be better if it was less dominent, prhaps the same tone as in the image.', '2005-04-16 19:45:34.000000', NULL, 1),
(1296820, 165226, 35530, '<td valign="top">The sepia tone doesn''t work for me on this one. Everythigs seems to blend together.</td>', 'The sepia tone doesn''t work for me on this one. Everythigs seems to blend together.', '2005-04-16 19:48:43.000000', NULL, 1),
(1296824, 164583, 35530, '<td valign="top">Here is a shot that probably could have been great if you were able to shoot a little closer. As it is, I find the debris scattered throughout the background to be very distracting. The old truck is awesome.</td>', 'Here is a shot that probably could have been great if you were able to shoot a little closer. As it is, I find the debris scattered throughout the background to be very distracting. The old truck is awesome.', '2005-04-16 19:53:10.000000', NULL, 1),
(1296827, 165011, 35530, '<td valign="top">I would have cropped out the road on this one, but make no mistakes...it is a stunning shot. Nicely done.</td>', 'I would have cropped out the road on this one, but make no mistakes...it is a stunning shot. Nicely done.', '2005-04-16 19:56:59.000000', NULL, 1),
(1296830, 165365, 35530, '<td valign="top">Great point of view. The curve of the road just forces your eyes to the building.</td>', 'Great point of view. The curve of the road just forces your eyes to the building.', '2005-04-16 19:59:20.000000', NULL, 1),
(1296833, 165667, 6814, '<td valign="top">This photo lacks interest because there is not enough detail in the shot.  I think it would have been better if you had been closer and shot a select portion of the building.</td>', 'This photo lacks interest because there is not enough detail in the shot.  I think it would have been better if you had been closer and shot a select portion of the building.', '2005-04-16 20:00:09.000000', NULL, 1),
(1296834, 166047, 35530, '<td valign="top">Nice shot. Lovely color</td>', 'Nice shot. Lovely color', '2005-04-16 20:00:18.000000', NULL, 1),
(1296836, 165616, 34547, '<td valign="top">...if the car wasn''t there...</td>', '...if the car wasn''t there...', '2005-04-16 20:01:03.000000', NULL, 1),
(1296837, 166089, 35530, '<td valign="top">Clever title as well as idea.</td>', 'Clever title as well as idea.', '2005-04-16 20:01:51.000000', NULL, 1),
(1296838, 164680, 6814, '<td valign="top">Unfortunately, the cropping on this shot is distracting.  either back up to get the whole building into the frame, or select just a portion of the building to focus on.</td>', 'Unfortunately, the cropping on this shot is distracting.  either back up to get the whole building into the frame, or select just a portion of the building to focus on.', '2005-04-16 20:02:23.000000', NULL, 1),
(1296842, 165675, 35530, '<td valign="top">Besides the small size, it seems out of focus.</td>', 'Besides the small size, it seems out of focus.', '2005-04-16 20:06:32.000000', NULL, 1),
(1296843, 164942, 6814, '<td valign="top">"One picture is worth a thousand words."  I would like this shot a lot better if the shadow in the foreground was not present.  Otherwise, this is a very evocative shot.</td>', '"One picture is worth a thousand words."  I would like this shot a lot better if the shadow in the foreground was not present.  Otherwise, this is a very evocative shot.', '2005-04-16 20:06:32.000000', NULL, 1),
(1296844, 163940, 34547, '<td valign="top">It could be good. It just looks a little dark in the foreground and soft in the sky. But it appeals to me.</td>', 'It could be good. It just looks a little dark in the foreground and soft in the sky. But it appeals to me.', '2005-04-16 20:06:43.000000', NULL, 1),
(1296847, 165983, 35530, '<td valign="top">Nice perspective. I like how rich the lighting makes the earth in front appear.</td>', 'Nice perspective. I like how rich the lighting makes the earth in front appear.', '2005-04-16 20:08:23.000000', NULL, 1),
