(1300571, 164943, 19708, '<td valign="top">Great composition. Your choice for making it a B&amp;W was a wise one.<br/>Well Done!</td>', 'Great composition. Your choice for making it a B&W was a wise one.Well Done!', '2005-04-18 13:38:38.000000', NULL, 1),
(1300573, 166137, 31541, '<td valign="top">Great colors and great texture!</td>', 'Great colors and great texture!', '2005-04-18 13:39:28.000000', NULL, 1),
